+use crate::irq::IrqSource;

 const IO_START: u32 = 0x0B0; // DMA0SAD, first DMA register
+const IO_END: u32 = 0x0DF; // last byte of DMA3CNT_H
+const CHANNEL_STRIDE: u32 = 12; // bytes of registers per channel
