+/// A FIFO request always moves 4 words (gbatek: Sound DMA (FIFO Timing Mode)).
+const FIFO_UNITS: u32 = 4;
+
+const DMA_IRQ_SOURCES: [IrqSource; 4] = [IrqSource::Dma0, IrqSource::Dma1, IrqSource::Dma2, IrqSource::Dma3];
